-- RentFlow initial PostgreSQL schema for Supabase
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('landlord','property_manager','tenant'); exception when duplicate_object then null; end $$;
do $$ begin create type public.unit_status as enum ('vacant','occupied','maintenance'); exception when duplicate_object then null; end $$;
do $$ begin create type public.invoice_status as enum ('draft','issued','partially_paid','paid','overdue','void'); exception when duplicate_object then null; end $$;
do $$ begin create type public.charge_type as enum ('rent','water','garbage','security','electricity','parking','maintenance','other'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text,role public.app_role not null default 'tenant',created_at timestamptz not null default now());
create table if not exists public.properties(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null,address text,city text,county text,created_at timestamptz not null default now());
create table if not exists public.units(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,unit_number text not null,monthly_rent numeric(12,2) not null default 0 check(monthly_rent>=0),water_fixed numeric(12,2) not null default 0 check(water_fixed>=0),water_rate numeric(12,2) not null default 0 check(water_rate>=0),garbage_fee numeric(12,2) not null default 0 check(garbage_fee>=0),security_fee numeric(12,2) not null default 0 check(security_fee>=0),status public.unit_status not null default 'vacant',created_at timestamptz not null default now(),unique(property_id,unit_number));
create table if not exists public.leases(id uuid primary key default gen_random_uuid(),unit_id uuid not null references public.units(id),tenant_id uuid not null references public.profiles(id),start_date date not null,end_date date,monthly_rent numeric(12,2) not null check(monthly_rent>=0),deposit_amount numeric(12,2) not null default 0 check(deposit_amount>=0),status text not null default 'active' check(status in('active','ended','pending')),created_at timestamptz not null default now());
create unique index if not exists one_active_lease_per_unit on public.leases(unit_id) where status='active';
create table if not exists public.invoices(id uuid primary key default gen_random_uuid(),lease_id uuid not null references public.leases(id),invoice_number text not null unique,period_start date not null,period_end date not null,due_date date not null,subtotal numeric(12,2) not null default 0,total_amount numeric(12,2) not null default 0,amount_paid numeric(12,2) not null default 0,status public.invoice_status not null default 'issued',notes text,created_at timestamptz not null default now(),check(total_amount>=0 and amount_paid>=0 and amount_paid<=total_amount));
create table if not exists public.invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,charge public.charge_type not null,description text not null,quantity numeric(12,3) not null default 1,unit_price numeric(12,2) not null default 0,amount numeric(12,2) not null default 0,created_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id),tenant_id uuid not null references public.profiles(id),amount numeric(12,2) not null check(amount>0),method text not null check(method in('mpesa','bank','cash','other')),transaction_reference text,payment_date timestamptz not null default now(),status text not null default 'pending' check(status in('pending','confirmed','failed','reversed')),recorded_by uuid references public.profiles(id),created_at timestamptz not null default now());
create unique index if not exists unique_payment_reference on public.payments(method,transaction_reference) where transaction_reference is not null;
create table if not exists public.water_readings(id uuid primary key default gen_random_uuid(),unit_id uuid not null references public.units(id),reading_date date not null,previous_reading numeric(12,3) not null,current_reading numeric(12,3) not null,rate numeric(12,2) not null,amount numeric(12,2) generated always as ((current_reading-previous_reading)*rate) stored,notes text,created_at timestamptz not null default now(),check(current_reading>=previous_reading),unique(unit_id,reading_date));
create table if not exists public.maintenance_requests(id uuid primary key default gen_random_uuid(),unit_id uuid not null references public.units(id),tenant_id uuid not null references public.profiles(id),title text not null,description text,priority text not null default 'normal' check(priority in('low','normal','high','urgent')),status text not null default 'open' check(status in('open','in_progress','resolved','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists invoices_due_idx on public.invoices(due_date,status);
create index if not exists payments_tenant_date_idx on public.payments(tenant_id,payment_date desc);
create index if not exists leases_tenant_idx on public.leases(tenant_id,status);
create or replace function public.owns_unit(p_unit_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from units u join properties p on p.id=u.property_id where u.id=p_unit_id and p.owner_id=auth.uid()); $$;
create or replace function public.is_tenant_on_unit(p_unit_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from leases l where l.unit_id=p_unit_id and l.tenant_id=auth.uid() and l.status='active'); $$;
-- Prevent users from promoting themselves by editing profiles.role.
create or replace function public.protect_profile_role() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.role is distinct from old.role and coalesce(auth.jwt()->>'role','') <> 'service_role' then raise exception 'Role changes require an authorized administrator'; end if; return new; end; $$;
drop trigger if exists protect_profile_role_trigger on public.profiles;
create trigger protect_profile_role_trigger before update on public.profiles for each row execute function public.protect_profile_role();
alter table public.profiles enable row level security;
alter table public.properties enable row level security;
alter table public.units enable row level security;
alter table public.leases enable row level security;
alter table public.invoices enable row level security;
alter table public.invoice_items enable row level security;
alter table public.payments enable row level security;
alter table public.water_readings enable row level security;
alter table public.maintenance_requests enable row level security;
alter table public.audit_logs enable row level security;
drop policy if exists profiles_self_read on public.profiles;
create policy profiles_self_read on public.profiles for select using(id=auth.uid());
drop policy if exists properties_owner_all on public.properties;
create policy properties_owner_all on public.properties for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists units_owner_all on public.units;
create policy units_owner_all on public.units for all using(exists(select 1 from public.properties p where p.id=property_id and p.owner_id=auth.uid())) with check(exists(select 1 from public.properties p where p.id=property_id and p.owner_id=auth.uid()));
drop policy if exists units_tenant_read on public.units;
create policy units_tenant_read on public.units for select using(public.is_tenant_on_unit(id));
drop policy if exists leases_landlord_read on public.leases;
create policy leases_landlord_read on public.leases for select using(public.owns_unit(unit_id));
drop policy if exists leases_tenant_read on public.leases;
create policy leases_tenant_read on public.leases for select using(tenant_id=auth.uid());
drop policy if exists leases_landlord_manage on public.leases;
create policy leases_landlord_manage on public.leases for all using(public.owns_unit(unit_id)) with check(public.owns_unit(unit_id));
drop policy if exists invoices_landlord_read on public.invoices;
create policy invoices_landlord_read on public.invoices for select using(exists(select 1 from public.leases l where l.id=lease_id and public.owns_unit(l.unit_id)));
drop policy if exists invoices_tenant_read on public.invoices;
create policy invoices_tenant_read on public.invoices for select using(exists(select 1 from public.leases l where l.id=lease_id and l.tenant_id=auth.uid()));
drop policy if exists invoice_items_visible on public.invoice_items;
create policy invoice_items_visible on public.invoice_items for select using(exists(select 1 from public.invoices i join public.leases l on l.id=i.lease_id where i.id=invoice_id and (l.tenant_id=auth.uid() or public.owns_unit(l.unit_id))));
drop policy if exists invoice_items_landlord_manage on public.invoice_items;
create policy invoice_items_landlord_manage on public.invoice_items for all using(exists(select 1 from public.invoices i join public.leases l on l.id=i.lease_id where i.id=invoice_id and public.owns_unit(l.unit_id))) with check(exists(select 1 from public.invoices i join public.leases l on l.id=i.lease_id where i.id=invoice_id and public.owns_unit(l.unit_id)));
drop policy if exists payments_tenant_read on public.payments;
create policy payments_tenant_read on public.payments for select using(tenant_id=auth.uid());
drop policy if exists payments_landlord_read on public.payments;
create policy payments_landlord_read on public.payments for select using(exists(select 1 from public.invoices i join public.leases l on l.id=i.lease_id where i.id=invoice_id and public.owns_unit(l.unit_id)));
drop policy if exists payments_landlord_record on public.payments;
create policy payments_landlord_record on public.payments for insert with check(recorded_by=auth.uid() and exists(select 1 from public.invoices i join public.leases l on l.id=i.lease_id where i.id=invoice_id and public.owns_unit(l.unit_id)));
drop policy if exists water_owner_all on public.water_readings;
create policy water_owner_all on public.water_readings for all using(public.owns_unit(unit_id)) with check(public.owns_unit(unit_id));
drop policy if exists water_tenant_read on public.water_readings;
create policy water_tenant_read on public.water_readings for select using(public.is_tenant_on_unit(unit_id));
drop policy if exists maintenance_tenant_create on public.maintenance_requests;
create policy maintenance_tenant_create on public.maintenance_requests for insert with check(tenant_id=auth.uid() and public.is_tenant_on_unit(unit_id));
drop policy if exists maintenance_tenant_read on public.maintenance_requests;
create policy maintenance_tenant_read on public.maintenance_requests for select using(tenant_id=auth.uid());
drop policy if exists maintenance_owner_manage on public.maintenance_requests;
create policy maintenance_owner_manage on public.maintenance_requests for all using(public.owns_unit(unit_id)) with check(public.owns_unit(unit_id));
drop policy if exists audit_actor_read on public.audit_logs;
create policy audit_actor_read on public.audit_logs for select using(actor_id=auth.uid());
